#!/usr/bin/env python3
import sys
import os
import subprocess

try:
    import psycopg2
except ImportError:
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', 'psycopg2-binary'])
    import psycopg2

DB_CONFIG = {
    "host": "172.17.0.1",
    "port": "5432",
    "user": "postgres",
    "password": "password",
    "dbname": "postgres"
}

BLOCKED_PATTERNS = ['DROP', 'SELECT *', 'pg_shadow', ';']


def validate_username(username):
    """Return False if username contains any blocked patterns, True otherwise."""
    if not isinstance(username, str):
        return False
    for pattern in BLOCKED_PATTERNS:
        if pattern in username:
            return False
    return True


def execute_user_search(username):
    """Only runs the query if validate_username returns True."""
    if not validate_username(username):
        print(f"Invalid username: contains blocked pattern. Query rejected.", file=sys.stderr)
        return None

    conn = psycopg2.connect(**DB_CONFIG)
    conn.autocommit = True
    cur = conn.cursor()
    try:
        query = f"SELECT username, email FROM users WHERE username = '{username}'"
        cur.execute(query)
        if cur.description is not None:
            columns = [desc[0] for desc in cur.description]
            rows = cur.fetchall()
            print(" | ".join(columns))
            for row in rows:
                print(" | ".join("" if v is None else str(v) for v in row))
            return rows
        else:
            print("Query executed successfully.")
            return None
    finally:
        cur.close()
        conn.close()


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python safe_query.py <username>", file=sys.stderr)
        sys.exit(1)
    try:
        execute_user_search(sys.argv[1])
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
